You want a **simple code for searching in a Singly Linked List (SLL)**.  

Here’s the **basic C code** for searching an element:  

```c
#include <stdio.h>
#include <stdlib.h>

// Structure of a node
struct Node {
    int data;
    struct Node* next;
};

// Function to search an element in the SLL
int search(struct Node* head, int key) {
    struct Node* temp = head;
    int position = 1;  // Position counter starts from 1

    while (temp != NULL) {
        if (temp->data == key) {
            return position;  // Key found
        }
        temp = temp->next;
        position++;
    }
    return -1; // Key not found
}

// Function to create a new node
struct Node* createNode(int data) {
    struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
    newNode->data = data;
    newNode->next = NULL;
    return newNode;
}

int main() {
    // Creating nodes
    struct Node* head = createNode(10);
    head->next = createNode(20);
    head->next->next = createNode(30);
    head->next->next->next = createNode(40);

    int key = 30;

    int pos = search(head, key);

    if (pos != -1)
        printf("Element %d found at position %d\n", key, pos);
    else
        printf("Element %d not found in the list\n", key);

    return 0;
}
```

### 🔑 Explanation:
1. Traverse the linked list starting from `head`.
2. Compare each node’s `data` with the given `key`.
3. If found → return its position.  
4. If not found till the end → return `-1`.  

👉 Output for this code (searching **30**):  
```
Element 30 found at position 3
```

