### 5️⃣ Delete at End
```c
void deleteAtEnd(struct Node** head) {
    if (*head == NULL) return;

    if ((*head)->next == *head) {  // Only one node
        free(*head);
        *head = NULL;
        return;
    }

    struct Node* temp = *head;
    while (temp->next->next != *head) temp = temp->next;

    free(temp->next);
    temp->next = *head;
}
